# -*- coding: utf-8 -*-
# Catechism bank — the Iẓhār Q&A, bāb 2 (the governed word), items 26–50.
ITEMS = [
 {"n": 26, "q": {"tr": "Haberde asıl olan nedir? Haberin hazfi câiz midir?", "en": "What is the root state of the khabar, and may it be dropped?"},
  "a": {"tr": "Haberde asıl olan nekre olmaktır; ancak bazen ma'rife olabilir (اللهُ إِلَهُنَا). Karine olduğunda haberin hazfi câizdir: «أَزَيْدٌ قَائِمٌ أَمْ عَمْرٌو» sorusuna cevaben «زَيْدٌ» demek gibi.", "en": "Its root is to be indefinite, though it may be definite (اللهُ إِلَهُنَا). With a clue it may be dropped: answering «أَزَيْدٌ قَائِمٌ أَمْ عَمْرٌو» with «زَيْدٌ»."},
  "ar": ["اللهُ إِلَهُنَا"], "notes": ["khabar-al-mubtada-wa-ahkamuh"]},
 {"n": 27, "q": {"tr": "Habere fânın dühûlü ne zaman vâcib olur?", "en": "When must the fāʾ enter the khabar?"},
  "a": {"tr": "Mübtedâ أَمَّا'dan sonra olursa haberine fânın dühûlü vâcibdir (أَمَّا زَيْدٌ فَمُنْطَلِقٌ). Şiir zarureti olursa veya kavli gizlemek için olursa vâcib değildir.", "en": "When the mubtadaʾ follows أَمَّا (أَمَّا زَيْدٌ فَمُنْطَلِقٌ); not in poetic necessity, nor where a qawl is concealed."},
  "ar": ["أَمَّا زَيْدٌ فَمُنْطَلِقٌ"], "notes": ["al-fa-fi-khabar-al-mubtada", "amma-tafsiliyya"]},
 {"n": 28, "q": {"tr": "Habere fânın dühûlü ne zaman câiz olur?", "en": "When may the fāʾ enter the khabar?"},
  "a": {"tr": "On dört yerde: mübtedâ fiil ile veya zarf ile sılalanmış ism-i mevsûl olursa (الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ؛ الَّذِي فِي الدَّارِ فَلَهُ دِرْهَمٌ); böyle bir mevsûl ile mevsûf olursa; fiil ile veya zarf ile vasıflanmış nekre olursa (رَجُلٌ يَأْتِينِي فَلَهُ دِرْهَمٌ); böyle bir mevsûle veya mevsûfa muzâf olursa (غُلَامُ الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ); fiil ile mevsûf nekreye muzâf olursa; müfred ile mevsûf nekreye muzâf olan كُلّ lafzı olursa (كُلُّ رَجُلٍ عَالِمٍ فَلَهُ دِرْهَمٌ); aslâ mevsûf olmayan nekreye muzâf كُلّ olursa (كُلُّ رَجُلٍ فَلَهُ دِرْهَمٌ). Bu on dört yere إِنَّ، أَنَّ، لَكِنَّ girerse yine câizdir.", "en": "In fourteen places: a relative mubtadaʾ whose ṣila is a verb or a ẓarf (الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ؛ الَّذِي فِي الدَّارِ فَلَهُ دِرْهَمٌ); a noun described by such a relative; an indefinite described by a verb or a ẓarf (رَجُلٌ يَأْتِينِي فَلَهُ دِرْهَمٌ); a noun annexed to such a relative or such a described noun (غُلَامُ الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ); annexed to an indefinite described by a verb; كُلّ annexed to an indefinite described by a single word (كُلُّ رَجُلٍ عَالِمٍ فَلَهُ دِرْهَمٌ); كُلّ annexed to an undescribed indefinite (كُلُّ رَجُلٍ فَلَهُ دِرْهَمٌ). With إِنَّ، أَنَّ، لَكِنَّ entering these, it stays allowed."},
  "ar": ["الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ", "كُلُّ رَجُلٍ فَلَهُ دِرْهَمٌ"], "notes": ["al-fa-fi-khabar-al-mubtada", "fa-khabar-mubtada"]},
 {"n": 29, "q": {"tr": "كَانَ bâbının isminin hükmü nasıldır?", "en": "What is the ruling of the ism of كَانَ?"},
  "a": {"tr": "Yalnız isim veya isim te'vîlinde olmakta, âmili üzerine takdiminin câiz olmamasında, masdarın hâricinde hazfinin câiz olmamasında, zamir veya ism-i zâhir olmakta ve zamirin müstetir ve bâriz olmasında fâil gibidir.", "en": "Like the doer: a noun or construed as one; never put before its governor; never dropped except with the maṣdar; a pronoun or an overt noun; its pronoun hidden or apparent."},
  "ar": ["اسْمُ كَانَ"], "notes": ["al-marfuat-al-khamis-ila-al-tasi", "kana-wa-akhawatuha"]},
 {"n": 30, "q": {"tr": "إِنَّ bâbının haberinin hükmü nasıldır?", "en": "What is the ruling of the khabar of إِنَّ?"},
  "a": {"tr": "Taaddüdünün câiz olmasında, cümle olmakta, mezkûr ve mahzûf olmakta mübtedânın haberi gibidir. Ancak ismi üzerine takdimi câiz değildir; haber zarf olursa câiz olur (إِنَّ فِي الدَّارِ رَجُلًا).", "en": "Like the khabar of the mubtadaʾ in being multiplied, in being a sentence, in being stated or dropped. But it may not precede the ism — unless it is a ẓarf (إِنَّ فِي الدَّارِ رَجُلًا)."},
  "ar": ["إِنَّ فِي الدَّارِ رَجُلًا"], "notes": ["al-marfuat-al-khamis-ila-al-tasi", "inna-wa-akhawatuha"]},
 {"n": 31, "q": {"tr": "Cins nefyi için olan لَا'nın haberinin hükmü nasıldır?", "en": "What is the ruling of the khabar of the genus-denying لَا?"},
  "a": {"tr": "Taaddüdünün câiz olmasında, cümle olmakta, mezkûr ve mahzûf olmakta mübtedânın haberi gibidir (لَا غُلَامَ رَجُلٍ عِنْدَنَا).", "en": "Like the khabar of the mubtadaʾ in being multiplied, a sentence, stated or dropped (لَا غُلَامَ رَجُلٍ عِنْدَنَا)."},
  "ar": ["لَا غُلَامَ رَجُلٍ عِنْدَنَا"], "notes": ["al-marfuat-al-khamis-ila-al-tasi", "la-nafiya-lil-jins"]},
 {"n": 32, "q": {"tr": "لَيْسَ'ye benzeyen مَا ve لَا'nın isminin hükmü nasıldır?", "en": "What is the ruling of the ism of مَا and لَا like لَيْسَ?"},
  "a": {"tr": "İsim veya isim te'vîlinde olmakta, atıf harfi olmaksızın taaddüdünün câiz olmamasında, ma'rife veya hususîleşmiş nekre olmakta mübtedâ gibidir.", "en": "Like the mubtadaʾ: a noun or construed as one; not multiplied without a conjunction; definite or an indefinite made particular."},
  "ar": ["اسْمُ مَا وَلَا الْمُشَبَّهَتَيْنِ بِلَيْسَ"], "notes": ["al-marfuat-al-khamis-ila-al-tasi", "ma-la-mushabbaha"]},
 {"n": 33, "q": {"tr": "Ma'mûl-i mansub kaçtır?", "en": "How many manṣūb governed words are there?"},
  "a": {"tr": "On üç: mef'ûl-i mutlak, mef'ûl bih, mef'ûl fîh, mef'ûl leh, mef'ûl maah, hâl, temyiz, müstesnâ, كَانَ bâbının haberi, إِنَّ bâbının ismi, cins nefyi için olan لَا'nın ismi, لَيْسَ'ye benzeyen مَا ve لَا'nın haberi, nevâsıbdan biri giren fiil-i muzâri.", "en": "Thirteen: the mafʿūl muṭlaq, the mafʿūl bih, the mafʿūl fīh, the mafʿūl lahu, the mafʿūl maʿah, the ḥāl, the tamyīz, the mustathnā, the khabar of كَانَ, the ism of إِنَّ, the ism of the genus-denying لَا, the khabar of مَا and لَا like لَيْسَ, and the muḍāriʿ under a nāṣib."},
  "ar": ["الْمَنْصُوبَاتُ ثَلَاثَةَ عَشَرَ"], "notes": ["al-mansubat-al-maful-al-mutlaq"]},
 {"n": 34, "q": {"tr": "Mef'ûl-i mutlakın tarifi nedir?", "en": "How is the mafʿūl muṭlaq defined?"},
  "a": {"tr": "Lafzan veya takdiren mef'ûl-i mutlak mânâsına mezkûr âmilin fâilinin işlemiş olduğu şeyin ismidir (ضَرَبْتُ ضَرْبًا، ضِرْبَةً، ضَرْبَةً).", "en": "The name of what the doer of a governor — stated in wording or implied, and sharing its sense — has done (ضَرَبْتُ ضَرْبًا، ضِرْبَةً، ضَرْبَةً)."},
  "ar": ["اسْمُ مَا فَعَلَهُ فَاعِلُ عَامِلٍ مَذْكُورٍ لَفْظًا أَوْ تَقْدِيرًا بِمَعْنَاهُ"], "notes": ["al-mansubat-al-maful-al-mutlaq", "maful-mutlaq"]},
 {"n": 35, "q": {"tr": "Mef'ûl-i mutlakın fiilini hazfetmek câiz midir?", "en": "May the verb of the mafʿūl muṭlaq be dropped?"},
  "a": {"tr": "Karine kâim olduğunda câizdir: أَيْضًا gibi (aslı آضَ أَيْضًا). Mef'ûl-i mutlakın âmili üzerine takdimi de câizdir.", "en": "With a clue, yes: أَيْضًا (from آضَ أَيْضًا). The mafʿūl muṭlaq may also precede its governor."},
  "ar": ["آضَ أَيْضًا"], "notes": ["al-mansubat-al-maful-al-mutlaq", "maful-mutlaq"]},
 {"n": 36, "q": {"tr": "Mef'ûl bih nedir? Kaç kısımdır?", "en": "What is the mafʿūl bih, and how many kinds has it?"},
  "a": {"tr": "Fâilin fiili kendisi üzerine vâki olan şeyin ismidir. İki kısımdır: âm — harf-i cer ile mecrûrdur; hâs — müteaddîye mahsustur.", "en": "The name of that upon which the doer's act falls. Two kinds: the general, majrūr by a jarr letter; and the particular, proper to the transitive verb."},
  "ar": ["اسْمُ مَا وَقَعَ عَلَيْهِ فِعْلُ الْفَاعِلِ"], "notes": ["al-maful-bihi-wa-qismah", "maful-bihi"]},
 {"n": 37, "q": {"tr": "Mef'ûl bihin hazfi, fiilinin hazfi ve âmili üzerine takdimi câiz midir?", "en": "May the object, or its verb, be dropped, and may the object precede its governor?"},
  "a": {"tr": "Mef'ûl bihin hazfi, karine ile de fiilinin hazfi câizdir: «مَنْ أَضْرِبُ» diyene «زَيْدًا» demek gibi. Âmili üzerine takdimi de câizdir.", "en": "The object may be dropped, and with a clue its verb too: answering «مَنْ أَضْرِبُ» with «زَيْدًا». It may also precede its governor."},
  "ar": ["مَنْ أَضْرِبُ"], "notes": ["al-maful-bihi-wa-qismah", "hadhf-al-maful"]},
 {"n": 38, "q": {"tr": "Mef'ûl fîh nedir? Nasb olmasının şartı nedir?", "en": "What is the mafʿūl fīh, and what is the condition of its naṣb?"},
  "a": {"tr": "Zamandan veya mekândan, âmilinin mânâsı kendisinde işlenilen şeyin ismidir. Nasb olmasının şartı فِي'nin gizlenmesidir; فِي lafızda olsa cer îcab eder. فِي zarf-ı zaman-ı mübhem ve mahdûdda ve zarf-ı mekân-ı mübhemde gizlenir; zarf-ı mekân-ı mahdûdda ise yalnız دَخَلَ، نَزَلَ، سَكَنَ'den sonra gizlenir.", "en": "The name of the time or place in which the governor's sense is done. The condition of its naṣb is that فِي be hidden — stated, فِي would give jarr. It is hidden with the vague and bounded time-ẓarf and the vague place-ẓarf; with the bounded place-ẓarf only after دَخَلَ، نَزَلَ، سَكَنَ."},
  "ar": ["اسْمُ مَا فُعِلَ فِيهِ مَضْمُونُ عَامِلِهِ مِنْ زَمَانٍ أَوْ مَكَانٍ"], "notes": ["al-maful-fih-wal-maful-lah", "maful-fih"]},
 {"n": 39, "q": {"tr": "Mef'ûl leh nedir? Lafzan nasb olmasının şartı nedir?", "en": "What is the mafʿūl lahu, and what is the condition of its naṣb in wording?"},
  "a": {"tr": "Âmilinin mânâsı kendisi için işlenen şeyin ismidir. Lafzan nasbının şartı lâmı gizlemektir; bunun bahsi harf-i cer bahsinde geçti.", "en": "The name of that for whose sake the governor's sense is done. Its naṣb in wording requires the lām to be hidden — discussed under the jarr letters."},
  "ar": ["اسْمُ مَا فُعِلَ لِأَجْلِهِ مَضْمُونُ عَامِلِهِ"], "notes": ["al-maful-fih-wal-maful-lah", "maful-lah"]},
 {"n": 40, "q": {"tr": "Mef'ûl maah nedir? Ahvâlini beyan ediniz.", "en": "What is the mafʿūl maʿah, and what are its rules?"},
  "a": {"tr": "Âmilin ma'mûlüne arkadaşlık için vâvdan sonra zikrolunandır. Âmili ve arkadaş olduğu ma'mûl üzerine takdimi ve taaddüdü câiz değildir.", "en": "What is mentioned after the wāw for accompanying a governor's dependent. It may neither precede its governor or its companion, nor be multiplied."},
  "ar": ["الْمَذْكُورُ بَعْدَ الْوَاوِ لِمُصَاحَبَةِ مَعْمُولِ عَامِلٍ"], "notes": ["al-maful-maah-wal-hal", "maful-maah"]},
 {"n": 41, "q": {"tr": "Hâl nedir? Hâlin âmili nelerdir?", "en": "What is the ḥāl, and what governs it?"},
  "a": {"tr": "Lafzan veya mânen fâilin veya mef'ûl bihin hey'etini beyan eden şeydir. Âmili fiil (ضَرَبْتُ زَيْدًا قَائِمًا), şibh-i fiil (زَيْدٌ مَضْرُوبٌ قَائِمًا) veya mânâ-yı fiil (هَذَا زَيْدٌ قَائِمًا) olur.", "en": "What shows the state of the doer or the object, in wording or in sense. Its governor is a verb (ضَرَبْتُ زَيْدًا قَائِمًا), a verb-like word (زَيْدٌ مَضْرُوبٌ قَائِمًا) or a verb-sense word (هَذَا زَيْدٌ قَائِمًا)."},
  "ar": ["مَا يُبَيِّنُ هَيْئَةَ الْفَاعِلِ أَوِ الْمَفْعُولِ بِهِ لَفْظًا أَوْ مَعْنًى", "هَذَا زَيْدٌ قَائِمًا"], "notes": ["al-maful-maah-wal-hal", "hal"]},
 {"n": 42, "q": {"tr": "Hâlin ve zi'l-hâlin şartı nedir?", "en": "What is the condition of the ḥāl and of its owner?"},
  "a": {"tr": "Hâlin şartı nekre olmaktır; zi'l-hâl ise çoğu kere ma'rife olur.", "en": "The ḥāl must be indefinite; its owner is mostly definite."},
  "ar": ["الْحَالُ نَكِرَةٌ"], "notes": ["al-maful-maah-wal-hal", "hal"]},
 {"n": 43, "q": {"tr": "Hâlin, âmili ve zi'l-hâl üzerine takdimi câiz midir?", "en": "May the ḥāl precede its governor and its owner?"},
  "a": {"tr": "Hâl, âmil-i mânevî (mânâ-yı fiil) üzerine takaddüm edemez; zira onun ameli zayıftır. Zi'l-hâl sırf nekre olursa hâlin ona takdimi vâcib olur (جَاءَنِي رَاكِبًا رَجُلٌ). Mecrûr olan zi'l-hâl üzerine takdimi câiz değildir.", "en": "It may not precede a governor of meaning (a verb-sense word), whose power is weak. When the owner is a bare indefinite the ḥāl must precede it (جَاءَنِي رَاكِبًا رَجُلٌ). It may not precede an owner that is majrūr."},
  "ar": ["جَاءَنِي رَاكِبًا رَجُلٌ"], "notes": ["al-maful-maah-wal-hal", "mana-al-fil"]},
 {"n": 44, "q": {"tr": "Hâl cümle vâki olur mu? Olursa ne lâzım gelir?", "en": "Can the ḥāl be a sentence, and what does that require?"},
  "a": {"tr": "Hâl ancak cümle-i haberiyye olur; o zaman hâli zi'l-hâle bağlayacak bir râbıt lâzım gelir. Bu râbıt müsbet muzârilerde yalnız zamir olur; menfî muzâri, müsbet ve menfî mâzî ve cümle-i ismiyyede vâv ile beraber zamir, yalnız vâv veya yalnız zamir olur.", "en": "Only a declarative sentence; then a binder is needed to tie it to its owner. With an affirmative muḍāriʿ the binder is a pronoun alone; with a negated muḍāriʿ, a māḍī affirmative or negated, or a nominal sentence, it is the wāw with a pronoun, the wāw alone, or the pronoun alone."},
  "ar": ["رَابِطُ الْحَالِ"], "notes": ["al-hal-jumla-wa-rabituha"]},
 {"n": 45, "q": {"tr": "Temyizin tarifi nedir? Kaç kısımdır?", "en": "How is the tamyīz defined, and how many kinds has it?"},
  "a": {"tr": "Mezkûr veya mukadder bir zattan yerleşmiş kapalılığı kaldırandır. İki kısımdır: mezkûr zattan kapalılığı kaldırır (عِشْرُونَ دِرْهَمًا، رِطْلٌ زَيْتًا، مَنَوَانِ سَمْنًا، عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا); mukadder zattan kapalılığı kaldırır (طَابَ زَيْدٌ نَفْسًا).", "en": "What lifts the settled vagueness off an essence, stated or implied. Two kinds: off a stated essence (عِشْرُونَ دِرْهَمًا، رِطْلٌ زَيْتًا، مَنَوَانِ سَمْنًا، عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا); off an implied one (طَابَ زَيْدٌ نَفْسًا)."},
  "ar": ["مَا يَرْفَعُ الْإِبْهَامَ الْمُسْتَقَرَّ عَنْ ذَاتٍ مَذْكُورَةٍ أَوْ مُقَدَّرَةٍ", "طَابَ زَيْدٌ نَفْسًا"], "notes": ["al-tamyiz-wa-ahkamuh", "tamyiz"]},
 {"n": 46, "q": {"tr": "Mukadder zattan kapalılığı kaldıran ikinci kısım temyiz nelerden kapalılığı kaldırır?", "en": "The second kind of tamyīz lifts vagueness from what?"},
  "a": {"tr": "Üç şeyden: cümledeki mukadder zattan (طَابَ زَيْدٌ نَفْسًا, aslı طَابَ شَيْءُ زَيْدٍ); şibh-i cümledeki mukadder zattan (زَيْدٌ طَيِّبٌ أَبًا); izâfetteki mukadder zattan (أَعْجَبَنِي طِيبُهُ نَفْسًا).", "en": "Three: the implied essence in a sentence (طَابَ زَيْدٌ نَفْسًا, from طَابَ شَيْءُ زَيْدٍ); in a quasi-sentence (زَيْدٌ طَيِّبٌ أَبًا); in an annexation (أَعْجَبَنِي طِيبُهُ نَفْسًا)."},
  "ar": ["زَيْدٌ طَيِّبٌ أَبًا", "أَعْجَبَنِي طِيبُهُ نَفْسًا"], "notes": ["al-tamyiz-wa-ahkamuh"]},
 {"n": 47, "q": {"tr": "Temyizin âmili üzerine takdimi câiz midir?", "en": "May the tamyīz precede its governor?"},
  "a": {"tr": "Âmili ism-i mübhem-i tâm olduğunda câiz değildir. Âmili fiil olduğunda da câiz değildir; çünkü temyiz mânâda fâildir ve fâilin fiil üzerine takdimi câiz değildir.", "en": "Not when its governor is a complete vague noun; nor when it is a verb — for the tamyīz is in meaning a doer, and a doer may not precede its verb."},
  "ar": ["تَقْدِيمُ التَّمْيِيزِ"], "notes": ["al-tamyiz-wa-ahkamuh"]},
 {"n": 48, "q": {"tr": "Müstesnâ kaç kısımdır? Tarifleri nedir? Birer misal veriniz.", "en": "How many kinds of mustathnā are there, with their definitions and an example of each?"},
  "a": {"tr": "İki. Müstesnâ-yı muttasıl: إِلَّا veya kardeşlerinden biri ile müteaddidden çıkarılandır (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا). Müstesnâ-yı munkatı': إِلَّا'dan sonra zikrolunup müteaddidden çıkarılmayandır (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا).", "en": "Two. The connected: what is taken out of a plurality by إِلَّا or one of its sisters (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا). The disconnected: what is mentioned after إِلَّا without being taken out of a plurality (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا)."},
  "ar": ["الْمُخْرَجُ عَنْ مُتَعَدِّدٍ بِإِلَّا أَوْ إِحْدَى أَخَوَاتِهَا", "جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا"], "notes": ["al-mustathna-wa-nawah-wa-nasbuh", "istithna"]},
 {"n": 49, "q": {"tr": "Müstesnânın nasbının vâcib olduğu yerler kaçtır?", "en": "In how many places is the naṣb of the mustathnā obligatory?"},
  "a": {"tr": "Dört: tâm mûcib kelâmda sıfatın gayrı إِلَّا'dan sonra vâki olduğunda (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا); müstesnâ minh üzerine takaddüm ettiğinde (جَاءَنِي إِلَّا زَيْدًا الْقَوْمُ); munkatı' olduğunda (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا); خَلَا، عَدَا، مَا خَلَا، مَا عَدَا، لَيْسَ، لَا يَكُونُ'dan sonra vâki olduğunda (جَاءَنِي الْقَوْمُ خَلَا زَيْدًا).", "en": "Four: after non-adjectival إِلَّا in complete affirmative speech (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا); when it precedes the mustathnā minhu (جَاءَنِي إِلَّا زَيْدًا الْقَوْمُ); when disconnected (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا); after خَلَا، عَدَا، مَا خَلَا، مَا عَدَا، لَيْسَ، لَا يَكُونُ (جَاءَنِي الْقَوْمُ خَلَا زَيْدًا)."},
  "ar": ["جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا", "مَا جَاءَنِي إِلَّا زَيْدًا أَحَدٌ"], "notes": ["al-mustathna-wa-nawah-wa-nasbuh"]},
 {"n": 50, "q": {"tr": "Müstesnânın diğer ahkâmı nasıldır?", "en": "What are the other rulings of the mustathnā?"},
  "a": {"tr": "Nasbının vâcib olmasından başka i'rab itibariyle üç hükmü daha vardır: müstesnâ minh mezkûr iken gayr-i mûcib kelâmda إِلَّا'dan sonra vâki olduğunda istisnâiyyet üzere nasb câiz, bedel tercih olunur (مَا جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا / إِلَّا زَيْدٌ); gayr-i mûcib kelâmda müstesnâ minh zikrolunmadığında müstesnâ, avâmil hasebi üzere i'rablanır (مَا ضَرَبَنِي إِلَّا زَيْدٌ); غَيْر، سِوَى، سَوَاء، حَاشَا، خَلَا، عَدَا'dan sonra mecrûr olur (جَاءَنِي الْقَوْمُ غَيْرَ زَيْدٍ).", "en": "Three more: after إِلَّا in negated speech with the mustathnā minhu stated, naṣb as exception is allowed and the badal preferred (مَا جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا / إِلَّا زَيْدٌ); in negated speech without it, the mustathnā is declined by the governors (مَا ضَرَبَنِي إِلَّا زَيْدٌ); after غَيْر، سِوَى، سَوَاء، حَاشَا، خَلَا، عَدَا it is majrūr (جَاءَنِي الْقَوْمُ غَيْرَ زَيْدٍ)."},
  "ar": ["مَا ضَرَبَنِي إِلَّا زَيْدٌ", "جَاءَنِي الْقَوْمُ غَيْرَ زَيْدٍ"], "notes": ["al-mustathna-badaluhu-wa-jarruh-wa-ghayr-wa-illa", "istithna-mufarragh"]},
]
